import{_ as e,o as r,c as a,a2 as d}from"./chunks/framework.CIXN0iHo.js";const b=JSON.parse('{"title":"Lab 1: 大模型qwen3 部署","description":"","frontmatter":{},"headers":[],"relativePath":"labs/lab1.md","filePath":"labs/lab1.md"}'),n={name:"labs/lab1.md"};function l(o,t,s,i,h,c){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="lab-1-大模型qwen3-部署" tabindex="-1">Lab 1: 大模型qwen3 部署 <a class="header-anchor" href="#lab-1-大模型qwen3-部署" aria-label="Permalink to &quot;Lab 1: 大模型qwen3 部署&quot;">​</a></h1><p><strong>个人作业 · 占总成绩 10% · 机器学习系统<code>ISTE6002P.01</code></strong></p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>DDL</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><strong>第 5 周周一(3.30) 23:59</strong></td></tr></tbody></table><hr><h2 id="_1-实验目标" tabindex="-1">1 实验目标 <a class="header-anchor" href="#_1-实验目标" aria-label="Permalink to &quot;1 实验目标&quot;">​</a></h2><ul><li>独立使用 <code>transformers</code> 运行 Qwen3，理解从输入文本到生成文本的完整链路</li><li>手动拆分 <strong>Prefill</strong> / <strong>Decode</strong> 两阶段并分别计时</li><li>分析输入长度、输出长度、batch size 对推理性能的影响规律</li></ul><hr><h2 id="_2-背景知识" tabindex="-1">2 背景知识 <a class="header-anchor" href="#_2-背景知识" aria-label="Permalink to &quot;2 背景知识&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>计算特征</th><th>瓶颈所在</th></tr></thead><tbody><tr><td><strong>Prefill</strong></td><td>并行处理全部输入 token，计算 KV Cache。<strong>Compute-bound</strong>，GPU 利用率高。</td><td>计算量随输入长度线性增长 → TTFT 上升</td></tr><tr><td><strong>Decode</strong></td><td>每步只生成 1 个 token，但需读取完整 KV Cache。<strong>Memory-bound</strong>，计算单元长期闲置。</td><td>内存带宽 &amp; KV Cache 大小 → TBT 瓶颈</td></tr></tbody></table><p><strong>性能指标说明：</strong></p><ul><li><strong>TTFT</strong>（Time to First Token）：首 token 延迟，反映 Prefill 耗时</li><li><strong>TBT</strong>（Time Between Tokens）：相邻 token 平均间隔，反映 Decode 单步耗时</li><li><strong>Throughput</strong>（tokens/s）：单位时间生成 token 总数</li><li><strong>峰值显存（GB）</strong>：推理过程中 GPU 显存最大占用</li></ul><hr><h2 id="_3-实验步骤" tabindex="-1">3 实验步骤 <a class="header-anchor" href="#_3-实验步骤" aria-label="Permalink to &quot;3 实验步骤&quot;">​</a></h2><h3 id="step-1-·-模型选择" tabindex="-1">Step 1 · 模型选择 <a class="header-anchor" href="#step-1-·-模型选择" aria-label="Permalink to &quot;Step 1 · 模型选择&quot;">​</a></h3><p>按显存选择模型：</p><table tabindex="0"><thead><tr><th style="text-align:left;">模型名称</th><th style="text-align:left;">官方下载链接 (Hugging Face)</th><th style="text-align:left;">预估权重显存占用</th><th style="text-align:left;">核心特点</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Qwen3-4B-Instruct-FP8</strong></td><td style="text-align:left;"><a href="https://huggingface.co/Qwen/Qwen3-4B-Instruct-2507-FP8" target="_blank" rel="noreferrer">Qwen/Qwen3-4B-Instruct-2507-FP8</a></td><td style="text-align:left;">~4.5 GB (FP8)</td><td style="text-align:left;"><strong>通用对话量化版</strong>：极低显存开销的通用对话模型，响应迅速，适合轻量级任务和快速部署，非思考模式。</td></tr><tr><td style="text-align:left;"><strong>Qwen3-4B-Instruct</strong></td><td style="text-align:left;"><a href="https://huggingface.co/Qwen/Qwen3-4B-Instruct-2507" target="_blank" rel="noreferrer">Qwen/Qwen3-4B-Instruct-2507</a></td><td style="text-align:left;">~8.0 GB (BF16/FP16)</td><td style="text-align:left;"><strong>全能长文与平衡</strong>：通用指令微调版，支持超长上下文，综合性能优异，适合日常对话、代码与 RAG，非思考模式。</td></tr></tbody></table><blockquote><p>想要快速上手 Qwen3，建议首先尝试使用 transformers 进行推理（<a href="https://huggingface.co/Qwen/Qwen3-4B-Instruct-2507-FP8#quickstart%EF%BC%89%EF%BC%8C" target="_blank" rel="noreferrer">https://huggingface.co/Qwen/Qwen3-4B-Instruct-2507-FP8#quickstart），</a> 会自动从 Hugging Face 的服务器下载model的权重（model.safetensors），默认地址~/.cache/huggingface/hub/。</p></blockquote><blockquote><p>注：如果Hugging Face下载太慢或经常断线，可以去ModelScope把权重文件下载下来，再将分词器和模型权重路径直接换成对应的本地路径。</p></blockquote><p><strong>可参考官方推理指南</strong>：<a href="https://qwen.readthedocs.io/en/latest/getting_started/quickstart.html" target="_blank" rel="noreferrer">https://qwen.readthedocs.io/en/latest/getting_started/quickstart.html</a></p><hr><h3 id="step-2-·-基础推理" tabindex="-1">Step 2 · 基础推理 <a class="header-anchor" href="#step-2-·-基础推理" aria-label="Permalink to &quot;Step 2 · 基础推理&quot;">​</a></h3><p>调用 <code>model.generate()</code> 跑通任意 prompt，截图终端输出与 <code>nvidia-smi</code>，作为报告中的提交内容。</p><blockquote><p><strong>参数探索</strong>：可以尝试修改 <code>temperature</code>、<code>top_p</code> 等解码参数，对比不同随机性设定下，模型输出表现的差异。</p></blockquote><hr><h3 id="step-3-·-prefill-decode-分段计时" tabindex="-1">Step 3 · Prefill / Decode 分段计时 <a class="header-anchor" href="#step-3-·-prefill-decode-分段计时" aria-label="Permalink to &quot;Step 3 · Prefill / Decode 分段计时&quot;">​</a></h3><p>不使用 <code>generate()</code>，手动拆分两阶段：</p><ul><li><strong>Prefill</strong>：单独调用 <code>model.forward(input_ids)</code>，记录耗时与 KV Cache 大小，即 TTFT</li><li><strong>Decode</strong>：循环调用 <code>model.forward(next_token, past_key_values=kv)</code>，记录每步耗时，计算 TBT 均值</li></ul><blockquote><p>提示：通过开启 use_cache=True，让模型吐出计算过程中产生的所有历史键值对 (outputs.past_key_values)在 prefill 结束后保留供 decode 复用，这正是实际推理框架的核心机制之一。</p></blockquote><p><strong>注：</strong> 想了解具体模型结构、Embedding、Forward或Generate的可以查看模型代码，下载模型后可以在 Transformers 库的源码中找到。</p><hr><h3 id="step-4-·-参数影响实验" tabindex="-1">Step 4 · 参数影响实验 <a class="header-anchor" href="#step-4-·-参数影响实验" aria-label="Permalink to &quot;Step 4 · 参数影响实验&quot;">​</a></h3><p>固定其余参数，每次只改变一个变量，填写以下三组表格。</p><h4 id="a-·-输入长度对-prefill-的影响" tabindex="-1">A · 输入长度对 Prefill 的影响 <a class="header-anchor" href="#a-·-输入长度对-prefill-的影响" aria-label="Permalink to &quot;A · 输入长度对 Prefill 的影响&quot;">​</a></h4><p>如固定 <code>output_len=128, batch=1</code></p><table tabindex="0"><thead><tr><th>指标</th><th style="text-align:center;">input=64</th><th style="text-align:center;">input=256</th><th style="text-align:center;">input=512</th><th style="text-align:center;">input=1024</th></tr></thead><tbody><tr><td>TTFT (ms)</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>Prefill Throughput (tok/s)</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>显存占用 (GB)</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><h4 id="b-·-输出长度对-decode-的影响" tabindex="-1">B · 输出长度对 Decode 的影响 <a class="header-anchor" href="#b-·-输出长度对-decode-的影响" aria-label="Permalink to &quot;B · 输出长度对 Decode 的影响&quot;">​</a></h4><p>如固定 <code>input_len=128, batch=1</code></p><table tabindex="0"><thead><tr><th>指标</th><th style="text-align:center;">output=64</th><th style="text-align:center;">output=256</th><th style="text-align:center;">output=512</th><th style="text-align:center;">output=1024</th></tr></thead><tbody><tr><td>TBT 均值 (ms)</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>Decode Throughput (tok/s)</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>KV Cache 增量 (GB)</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><h4 id="c-·-batch-size-的影响" tabindex="-1">C · Batch Size 的影响 <a class="header-anchor" href="#c-·-batch-size-的影响" aria-label="Permalink to &quot;C · Batch Size 的影响&quot;">​</a></h4><p>如固定 <code>input_len=128, output_len=128</code>（超出显存上限可跳过）</p><table tabindex="0"><thead><tr><th>指标</th><th style="text-align:center;">batch=1</th><th style="text-align:center;">batch=4</th><th style="text-align:center;">batch=8</th><th style="text-align:center;">batch=16</th></tr></thead><tbody><tr><td>TTFT (ms)</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>Throughput (tok/s)</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>内存占用 (GB)</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><hr><h2 id="_4-交付要求" tabindex="-1">4 交付要求 <a class="header-anchor" href="#_4-交付要求" aria-label="Permalink to &quot;4 交付要求&quot;">​</a></h2><h3 id="代码" tabindex="-1">代码 <a class="header-anchor" href="#代码" aria-label="Permalink to &quot;代码&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文件</th><th>说明</th></tr></thead><tbody><tr><td><code>infer.py</code></td><td>包含 prefill/decode 分离计时逻辑的完整推理脚本</td></tr><tr><td><code>benchmark.py</code></td><td>Step 4 三组实验的自动化测量脚本</td></tr><tr><td><code>requirements.txt</code> 或 <code>environment.yml</code></td><td>环境依赖</td></tr><tr><td><code>README.md</code></td><td>复现步骤与模型路径配置说明</td></tr></tbody></table><h3 id="实验报告-pdf" tabindex="-1">实验报告（PDF） <a class="header-anchor" href="#实验报告-pdf" aria-label="Permalink to &quot;实验报告（PDF）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>章节</th><th>内容要求</th></tr></thead><tbody><tr><td>1 环境配置</td><td>GPU 型号与显存、CUDA / PyTorch / transformers 版本、模型选择理由</td></tr><tr><td>2 实验数据</td><td>实验数据表，附prompt推理截图</td></tr><tr><td>3 数据分析</td><td>简单进行性能测试总结</td></tr></tbody></table><hr><h2 id="_5-评分标准-满分-100-折合总成绩-10" tabindex="-1">5 评分标准（满分 100，折合总成绩 10%） <a class="header-anchor" href="#_5-评分标准-满分-100-折合总成绩-10" aria-label="Permalink to &quot;5 评分标准（满分 100，折合总成绩 10%）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th style="text-align:center;">分值</th><th>说明</th></tr></thead><tbody><tr><td>代码可复现性</td><td style="text-align:center;">25</td><td>脚本可运行，README 清晰，依赖完整</td></tr><tr><td>Prefill / Decode 分离计时测试</td><td style="text-align:center;">25</td><td>两阶段独立测量，方法合理</td></tr><tr><td>三组参数实验数据完整</td><td style="text-align:center;">30</td><td>数据齐全，图表清晰</td></tr><tr><td>实验报告</td><td style="text-align:center;">20</td><td>结合数据，分析总结</td></tr></tbody></table><p><strong>提交方式</strong>：代码文件 + PDF 上传至研究生综合服务平台：<a href="https://yjs1.ustc.edu.cn/" target="_blank" rel="noreferrer">https://yjs1.ustc.edu.cn/</a></p><p><strong>提交格式</strong>：<code>学号_姓名_lab1.zip</code></p><hr>',53)])])}const u=e(n,[["render",l]]);export{b as __pageData,u as default};
